import { useState, useEffect, useCallback } from 'react';

const INITIAL = [
  { id: 1, name: 'Spell Tome', price: 30 },
  { id: 2, name: 'Magic Staff', price: 150 },
];

export default function ItemList() {
  const [items, setItems] = useState(INITIAL);
  const [selected, setSelected] = useState(null);

  // BUG 1: derived state — items.length should not be in state
  const [itemCount, setItemCount] = useState(items.length);
  useEffect(() => { setItemCount(items.length); }, [items]);

  // BUG 2: handler recreated every render
  const handleSelect = (id) => setSelected(id);

  return (
    // BUG 3: inline style object
    <div style={{ padding: 16, fontFamily: 'sans-serif' }}>
      <p>Count: {itemCount}</p>
      <ul>
        {items.map((item, i) => (
          // BUG 4: index key
          <li key={i}
              style={{ background: selected === item.id ? 'yellow' : 'white' }}
              onClick={() => handleSelect(item.id)}>
            {item.name}
          </li>
        ))}
      </ul>
    </div>
  );
}
